contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint a1, uint a2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(a1 > 0);
        require(a2 > 0);
        require(a1 <= type(uint).max / 2);
        require(a2 <= type(uint).max / 2);
        require(address(this).balance >= a1 + a2);
        require(address(c).balance >= a1 + a2);
        uint b = address(c).balance;
        c.sendTo(address(this), a1); if (__ESBMC_reverted()) return;
        uint mid = address(c).balance;
        c.sendTo(address(this), a2); if (__ESBMC_reverted()) return;
        uint fin = address(c).balance;
        assert(mid == b - a1 && fin == b - a1 - a2 && address(this).balance >= a1 + a2);
    }
    receive() external payable {}
}

