// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(uint256 a1, uint256 a2) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a1 > 0);
        vm.assume(a2 > 0);
        vm.assume(a1 <= type(uint).max / 2);
        vm.assume(a2 <= type(uint).max / 2);
        vm.assume(address(this).balance >= a1 + a2);
        vm.assume(address(c).balance >= a1 + a2);
        uint b = address(c).balance;
        try c.sendTo(address(this), a1) {} catch { return; }
        uint mid = address(c).balance;
        try c.sendTo(address(this), a2) {} catch { return; }
        uint fin = address(c).balance;
        assertTrue(mid == b - a1 && fin == b - a1 - a2 && address(this).balance >= a1 + a2);
    }

    function testFuzz_run(uint256 a1, uint256 a2) public {
        _run(a1, a2);
    }

    receive() external payable {}
}
